const SPRITE = (() => {
  const s = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  s.setAttribute('class', 'isprite');
  s.setAttribute('aria-hidden', 'true');
  // the aurora's gradients (stop colours in app.css): g-au across a shape's own width (the logo, the context ring),
  // g-au-i corner to corner of the icons' 24-unit box, so every icon wears it the same way, lines included
  const stops = '<stop class="au-a" offset="0"/><stop class="au-b" offset=".55"/><stop class="au-c" offset="1"/>';
  s.innerHTML = `<defs><linearGradient id="g-au">${stops}</linearGradient><linearGradient id="g-au-i" gradientUnits="userSpaceOnUse" x1="3" y1="3" x2="21" y2="21">${stops}</linearGradient></defs>` +
    Object.entries({ ...ICONS, 'wave-pulse-au': ICONS['wave-pulse'].replace('currentColor', 'url(#g-au)') })
      .map(([n, d]) => `<symbol id="i-${n}" viewBox="0 0 24 24" fill="none">${d}</symbol>`).join('');
  document.body.prepend(s);
  return s;
})();

const ic = (name, cls = '') => `<svg class="i${cls ? ' ' + cls : ''}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
// an icon in the aurora's gradient: auIcon makes its symbol the first time it's asked for and gives its name
const auIcon = (name) => {
  if (ICONS[name] && !document.getElementById(`i-${name}-au`)) {
    SPRITE.insertAdjacentHTML('beforeend', `<symbol id="i-${name}-au" viewBox="0 0 24 24" fill="none">${ICONS[name].replaceAll('currentColor', 'url(#g-au-i)')}</symbol>`);
  }
  return name + '-au';
};
const icAu = (name, cls = '') => ic(auIcon(name), cls);
